# COSINE=余弦相似度
def cosine_similarity(vector1, vector2):
    dot_product = sum(x * y for x, y in zip(vector1, vector2))
    magnitude1 = sum(x ** 2 for x in vector1) ** 0.5
    magnitude2 = sum(y ** 2 for y in vector2) ** 0.5
    similarity = dot_product / (magnitude1 * magnitude2)
    return similarity
# L2欧氏距离
def l2_similarity(vector1, vector2):
    difference = [x - y for x, y in zip(vector1, vector2)]
    similarity = sum(x ** 2 for x in difference) ** 0.5
    return similarity
# IP内积
def ip_similarity(vector1, vector2):
    similarity = sum(x * y for x, y in zip(vector1, vector2))
    return similarity

if __name__ == '__main__':
    similarity = cosine_similarity(vector1, vector2)
    print(f"Cosine similarity: {similarity:.2f}")
    similarity = l2_similarity(vector1, vector2)
    print(f"L2 similarity: {similarity:.2f}")
    similarity = ip_similarity(vector1, vector2)
    print(f"IP similarity: {similarity:.2f}")